import 'dart:io';import 'package:supabase_flutter/supabase_flutter.dart';import 'package:uuid/uuid.dart';import '../config/supabase_config.dart';import '../config/app_config.dart';
class MediaRepository{final c=SupabaseConfig.client;Future<String?>upload({required String partyId,required File file,required String mime,required int size,required String type})async{if(AppConfig.demoMode)return null;final id=const Uuid().v4();final uid=c.auth.currentUser!.id;final path='$partyId/$uid/$id/original';await c.rpc('create_media_post',params:{'p_id':id,'p_party_id':partyId,'p_media_type':type,'p_original_storage_path':path,'p_file_size':size,'p_mime_type':mime});await c.storage.from('party-media').upload(path,file);await c.rpc('media_upload_completed',params:{'mid':id});return id;}}
